CREATE TABLE IF NOT EXISTS ranked_players (player_id TEXT NOT NULL, season_number INTEGER NOT NULL, rp INTEGER NOT NULL DEFAULT 0, mmr INTEGER NOT NULL DEFAULT 1000, wins INTEGER NOT NULL DEFAULT 0, losses INTEGER NOT NULL DEFAULT 0, kills INTEGER NOT NULL DEFAULT 0, deaths INTEGER NOT NULL DEFAULT 0, assists INTEGER NOT NULL DEFAULT 0, games_played INTEGER NOT NULL DEFAULT 0, rank_protection INTEGER NOT NULL DEFAULT 1, previous_season_rank TEXT, PRIMARY KEY(player_id,season_number));
CREATE TABLE IF NOT EXISTS ranked_match_history (match_id TEXT PRIMARY KEY, player_id TEXT NOT NULL, season_number INTEGER NOT NULL, won INTEGER NOT NULL, rp_change INTEGER NOT NULL, kills INTEGER NOT NULL, deaths INTEGER NOT NULL, assists INTEGER NOT NULL, objective INTEGER NOT NULL DEFAULT 0, performance_rating INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ranked_seasons (season_number INTEGER PRIMARY KEY, name TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, reset_rp INTEGER NOT NULL DEFAULT 0, rewards_json TEXT NOT NULL DEFAULT '[]');
